def mul(P,R):
    A={}
    for e,c in P.items():
        for f,d in R.items():
            k=tuple(x+y for x,y in zip(e,f));A[k]=A.get(k,Q(0))+c*d
    return clean(A)
def moment(p,a,r):return Q(0) if r%p else Q(factorial(r),factorial(r//p))*a**(r//p)
