def position_monomial(e):
    n=len(e);A={(0,)*n:Q(1)}
    for i,r in enumerate(e):
        B={}
        for k in ([r] if i==0 else range(r+1)):
            f=[0]*n;f[i]=k
            if i:f[i-1]=r-k
            B[tuple(f)]=Q(comb(r,k)*(-1)**(r-k))
        A=mul(A,B)
